# Usage Example
if __name__ == "__main__":
    nx, ny = 16, 16
    Lx, Ly = 2*np.pi, 2*np.pi
    dx, dy = Lx/nx, Ly/ny
    nu = 0.1
    dt = 0.01
    diffusion_number = nu * dt * (1.0/dx**2 + 1.0/dy**2)
    # 本組參數的 diffusion_number 約為 0.01297，小於 1/2。
    if diffusion_number > 0.5:
        raise ValueError("顯式黏性步超限")

    solver = IncompressibleSolver(nx, ny, dx, dy, nu, dt)

    # Taylor–Green 形狀的 Stokes 模態初值
    for j in range(ny):
        y = (j + 0.5) * dy
        for i in range(nx + 1):
            x = i * dx
            solver.u[j, i] = np.sin(x) * np.cos(y)
    solver.u[:, nx] = solver.u[:, 0]

    for i in range(nx):
        x = (i + 0.5) * dx
        for j in range(ny + 1):
            y = j * dy
            solver.v[j, i] = -np.cos(x) * np.sin(y)
    solver.v[ny, :] = solver.v[0, :]

    for t in range(100):
        E, diagnostics = solver.step()
        if not diagnostics["poisson_residual_pass"]:
            raise RuntimeError("Poisson 真殘差未通過容差")
        if not diagnostics["divergence_pass"]:
            raise RuntimeError("投影後散度未通過容差")
        if t % 10 == 0:
            print(f"t={t*dt:.3f}, E={E:.6f}")
